from pathlib import Path

SCHED = Path("/sgl-workspace/sglang/python/sglang/srt/managers/scheduler_pp_mixin.py")
s = SCHED.read_text()

old = '''                if self.pp_group.is_first_rank:\n                    if cur_batch.forward_mode.is_extend() or cur_batch.is_extend_in_batch:\n                        _mtp_ids = getattr(cur_batch, "prefill_input_ids_cpu", None)\n                        if _mtp_ids is None:\n                            _mtp_ids = getattr(cur_batch, "input_ids", None)\n                        if _mtp_ids is None:\n                            raise RuntimeError(\n                                "[MTP-PP-SOURCE-MISSING] PP0 has neither "\n                                "prefill_input_ids_cpu nor input_ids"\n                            )\n                        cur_batch._mtp_pp_input_ids = _mtp_ids.to(\n                            self.device, non_blocking=True\n                        ).detach().clone()\n                        if cur_batch._mtp_pp_input_ids.numel() > 0:\n                            logger.info(\n                                "[MTP-PP-SOURCE-IDS] ids=[%d,%d] tokens=%d",\n                                int(cur_batch._mtp_pp_input_ids.min().item()),\n                                int(cur_batch._mtp_pp_input_ids.max().item()),\n                                int(cur_batch._mtp_pp_input_ids.numel()),\n                            )\n'''

new = '''                if self.pp_group.is_first_rank:\n                    if cur_batch.forward_mode.is_extend() or cur_batch.is_extend_in_batch:\n                        # prefill_input_ids_cpu is only an execution staging buffer and\n                        # can be rewritten with PP-local/proxy payloads while the same\n                        # ScheduleBatch is recycled. Reconstruct vocabulary ids from\n                        # authoritative Req fill state and the current extend range.\n                        _mtp_values = []\n                        _mtp_ranges = []\n                        for _req in cur_batch.reqs:\n                            _fill = _req.get_fill_ids()\n                            _range = getattr(_req, "extend_range", None)\n                            if _range is not None:\n                                _start = int(_range.start)\n                                _end = int(_range.end)\n                            else:\n                                _start = len(_req.prefix_indices)\n                                _end = len(_fill)\n                            _part = _fill[_start:_end]\n                            _mtp_values.extend(int(_tok) for _tok in _part)\n                            _mtp_ranges.append((_start, _end))\n\n                        _expected = int(getattr(cur_batch, "extend_num_tokens", len(_mtp_values)))\n                        if len(_mtp_values) != _expected:\n                            _staging = getattr(cur_batch, "prefill_input_ids_cpu", None)\n                            _staging_n = int(_staging.numel()) if _staging is not None else -1\n                            raise RuntimeError(\n                                "[MTP-PP-REQ-LEN] "\n                                f"reconstructed={len(_mtp_values)} expected={_expected} "\n                                f"staging={_staging_n} ranges={_mtp_ranges}"\n                            )\n\n                        cur_batch._mtp_pp_input_ids = torch.tensor(\n                            _mtp_values, dtype=torch.int64, device=self.device\n                        )\n                        if cur_batch._mtp_pp_input_ids.numel() > 0:\n                            _min_id = int(cur_batch._mtp_pp_input_ids.min().item())\n                            _max_id = int(cur_batch._mtp_pp_input_ids.max().item())\n                            _vocab = int(self.model_config.vocab_size)\n                            if _min_id < 0 or _max_id >= _vocab:\n                                raise RuntimeError(\n                                    "[MTP-PP-REQ-OOB] "\n                                    f"ids=[{_min_id},{_max_id}] vocab={_vocab} "\n                                    f"ranges={_mtp_ranges}"\n                                )\n                            _staging = getattr(cur_batch, "prefill_input_ids_cpu", None)\n                            if _staging is not None and _staging.numel() > 0:\n                                _smin = int(_staging.min().item())\n                                _smax = int(_staging.max().item())\n                                _sn = int(_staging.numel())\n                            else:\n                                _smin, _smax, _sn = 0, -1, 0\n                            logger.info(\n                                "[MTP-PP-REQ-SOURCE] ids=[%d,%d] tokens=%d "\n                                "staging=[%d,%d]/%d ranges=%s",\n                                _min_id, _max_id,\n                                int(cur_batch._mtp_pp_input_ids.numel()),\n                                _smin, _smax, _sn, _mtp_ranges,\n                            )\n'''

if "[MTP-PP-REQ-SOURCE]" in s:
    print("native MTP PP Req source patch already present")
elif old not in s:
    raise RuntimeError("native MTP PP source block not found")
else:
    s = s.replace(old, new, 1)
    SCHED.write_text(s)
    print("PATCHED native MTP PP source reconstruction from Req metadata")
    print(SCHED)
